#include <iostream>
#include <limits>

int main() {
    int id = 0;
    char name[30];
    char hometown[30];

    if (std::cin >> id) {
        // Discard remaining newline left by >>
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');

        // cin.getline automatically extracts and discards the '\n'
        std::cin.getline(name, 30);
        std::cin.getline(hometown, 30);

        std::cout << "ID: " << id
                  << " | Name: " << name
                  << " | Hometown: " << hometown << std::endl;
    }
    return 0;
}

#include <iostream>

int main() {
    double b = -345.678;

    std::cout.fill('*');
    std::cout.precision(2);
    std::cout.setf(std::ios::fixed, std::ios::floatfield);

    // Left alignment
    std::cout.setf(std::ios::left, std::ios::adjustfield);
    std::cout.width(10);
    std::cout << b << "\n";

    // Right alignment
    std::cout.setf(std::ios::right, std::ios::adjustfield);
    std::cout.width(10);
    std::cout << b << "\n";

    // Internal alignment
    std::cout.setf(std::ios::internal, std::ios::adjustfield);
    std::cout.width(10);
    std::cout << b << "\n";

    // Integer base formatting
    int num = 255;
    std::cout.setf(std::ios::hex, std::ios::basefield);
    std::cout << "Hex: " << num << "\n";
    std::cout.setf(std::ios::dec, std::ios::basefield);
    std::cout << "Dec: " << num << "\n";

    return 0;
}
